#include "s61_binary_deeper_cubic_field_20261101.hpp"
#include <chrono>
using namespace cubic_field;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
Fraction frac(const Poly&p){Fraction r;fmpq_mpoly_set(r.numerator,p.p,ctx);return r;}
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[2];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1];flint_free(s);}o<<'\n';fmpq_clear(q);}
struct Step{int swapcol;vector<Poly>scales,row;};
int main(int argc,char**argv){assert(argc==3);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]);ofstream out(argv[2]);assert(in&&out);int nr,nc,n,k;in>>nr>>nc>>n>>k;assert(k>0);vector<int>rr(n),cc(n),ff(k);for(int&i:rr)in>>i;for(int&i:cc)in>>i;for(int&i:ff)in>>i;vector<vector<Poly>>full(nr,vector<Poly>(nc));for(auto&r:full)for(auto&p:r)read_poly(in,p.p);vector<vector<Poly>>A(n,vector<Poly>(n+k));for(int i=0;i<n;i++){for(int j=0;j<n;j++)A[i][j]=full[rr[i]][cc[j]];for(int j=0;j<k;j++)A[i][n+j]=full[rr[i]][ff[j]];}vector<Step>steps;auto start=chrono::steady_clock::now();int orig=n;while(n){Poly g,h,q;vector<Poly>scale(n);for(int i=0;i<n;i++){fmpq_mpoly_zero(g.p,ctx);for(int j=0;j<n+k;j++){assert(fmpq_mpoly_gcd(h.p,g.p,A[i][j].p,ctx));g=h;if(fmpq_mpoly_is_fmpq(g.p,ctx)&&!fmpq_mpoly_is_zero(g.p,ctx))break;}assert(!fmpq_mpoly_is_zero(g.p,ctx));if(!fmpq_mpoly_is_fmpq(g.p,ctx))for(int j=0;j<n+k;j++){assert(fmpq_mpoly_divides(q.p,A[i][j].p,g.p,ctx));A[i][j]=q;} fmpq_t lc;fmpq_init(lc);int first=0;while(first<n+k&&fmpq_mpoly_is_zero(A[i][first].p,ctx))first++;assert(first<n+k);fmpq_mpoly_get_term_coeff_fmpq(lc,A[i][first].p,0,ctx);for(int j=0;j<n+k;j++)fmpq_mpoly_scalar_div_fmpq(A[i][j].p,A[i][j].p,lc,ctx);fmpq_clear(lc);}
for(int j=0;j<n;j++){fmpq_mpoly_zero(g.p,ctx);for(int i=0;i<n;i++){assert(fmpq_mpoly_gcd(h.p,g.p,A[i][j].p,ctx));g=h;if(fmpq_mpoly_is_fmpq(g.p,ctx)&&!fmpq_mpoly_is_zero(g.p,ctx))break;}assert(!fmpq_mpoly_is_zero(g.p,ctx));if(fmpq_mpoly_is_fmpq(g.p,ctx))fmpq_mpoly_one(g.p,ctx);scale[j]=g;if(!fmpq_mpoly_is_one(g.p,ctx))for(int i=0;i<n;i++){assert(fmpq_mpoly_divides(q.p,A[i][j].p,g.p,ctx));A[i][j]=q;}}
int bi=-1,bj=-1;long cost=100000000;for(int i=0;i<n;i++)for(int j=0;j<n;j++){long l=fmpq_mpoly_length(A[i][j].p,ctx);if(l&&l<cost){cost=l;bi=i;bj=j;}}assert(bi>=0);swap(A[0],A[bi]);for(auto&r:A)swap(r[0],r[bj]);swap(scale[0],scale[bj]);steps.push_back(Step{bj,scale,A[0]});vector<vector<Poly>>B(n-1,vector<Poly>(n-1+k));Poly x,y;for(int i=1;i<n;i++)for(int j=1;j<n+k;j++){fmpq_mpoly_mul(x.p,A[0][0].p,A[i][j].p,ctx);fmpq_mpoly_mul(y.p,A[i][0].p,A[0][j].p,ctx);fmpq_mpoly_sub(B[i-1][j-1].p,x.p,y.p,ctx);}A=std::move(B);n--;long terms=0;for(auto&r:A)for(auto&p:r)terms+=fmpq_mpoly_length(p.p,ctx);double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();cerr<<"SCHUR "<<n<<" TERMS "<<terms<<" PIVTERMS "<<cost<<" SEC "<<sec<<'\n';assert(sec<60&&terms<2000000);}
vector<vector<Fraction>>sol(k);for(auto it=steps.rbegin();it!=steps.rend();it++){int size=it->scales.size();for(int rhs=0;rhs<k;rhs++){Fraction x;for(int j=1;j<size;j++)if(!fmpq_mpoly_is_zero(it->row[j].p,ctx))x=subtract(x,multiply(frac(it->row[j]),sol[rhs][j-1]));x=subtract(x,frac(it->row[size+rhs]));x=divide(x,frac(it->row[0]));vector<Fraction>y;y.push_back(x);for(auto &v:sol[rhs])y.push_back(v);for(int j=0;j<size;j++)y[j]=divide(y[j],frac(it->scales[j]));swap(y[0],y[it->swapcol]);sol[rhs]=std::move(y);}}
for(int rhs=0;rhs<k;rhs++){Poly den,g,q,tmp;fmpq_mpoly_one(den.p,ctx);for(auto&v:sol[rhs]){assert(fmpq_mpoly_gcd(g.p,den.p,v.denominator,ctx));assert(fmpq_mpoly_divides(q.p,v.denominator,g.p,ctx));fmpq_mpoly_mul(tmp.p,den.p,q.p,ctx);den=tmp;}vector<Poly>num(nc);num[ff[rhs]]=den;for(int j=0;j<orig;j++){assert(fmpq_mpoly_divides(q.p,den.p,sol[rhs][j].denominator,ctx));fmpq_mpoly_mul(num[cc[j]].p,sol[rhs][j].numerator,q.p,ctx);}fmpq_mpoly_set(g.p,den.p,ctx);for(auto&p:num){assert(fmpq_mpoly_gcd(tmp.p,g.p,p.p,ctx));g=tmp;}if(!fmpq_mpoly_is_fmpq(g.p,ctx)){for(auto&p:num){assert(fmpq_mpoly_divides(q.p,p.p,g.p,ctx));p=q;}assert(fmpq_mpoly_divides(q.p,den.p,g.p,ctx));den=q;}for(int i=0;i<nr;i++){Poly z;for(int j=0;j<nc;j++)if(!fmpq_mpoly_is_zero(full[i][j].p,ctx)&&!fmpq_mpoly_is_zero(num[j].p,ctx)){fmpq_mpoly_mul(tmp.p,full[i][j].p,num[j].p,ctx);fmpq_mpoly_add(z.p,z.p,tmp.p,ctx);}assert(fmpq_mpoly_is_zero(z.p,ctx));}out<<"KERNEL "<<rhs<<'\n';write(out,den);for(auto&p:num)write(out,p);cerr<<"EXACT_FULL_KERNEL "<<rhs<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}out.flush();assert(out.good());}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
